import{_ as t,o as e,a as r,d as o}from"./chunks/framework.IehvnstE.js";const g=JSON.parse('{"title":"FAQ","description":"Часто задаваемые вопросы о Stuzhik. Решение проблем: OutOfMemoryError, краши, конфликты модов. Поддержка Forge, Fabric, NeoForge, Quilt.","frontmatter":{"description":"Часто задаваемые вопросы о Stuzhik. Решение проблем: OutOfMemoryError, краши, конфликты модов. Поддержка Forge, Fabric, NeoForge, Quilt.","head":[["meta",{"name":"keywords","content":"stuzhik faq, стужик, minecraft лаунчер проблемы, outofmemoryerror minecraft, краш minecraft моды, forge fabric quilt neoforge"}]]},"headers":[],"relativePath":"faq.md","filePath":"faq.md"}'),i={name:"faq.md"};function n(h,a,l,d,s,c){return e(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><p>Короткие ответы на частые вопросы. Подробности по каждой теме в разделах справки, ссылки в ответах.</p><h2 id="общие-вопросы" tabindex="-1">Общие вопросы <a class="header-anchor" href="#общие-вопросы" aria-label="Permalink to &quot;Общие вопросы&quot;">​</a></h2><h3 id="чем-отличается-от-других-лаунчеров" tabindex="-1">Чем отличается от других лаунчеров? <a class="header-anchor" href="#чем-отличается-от-других-лаунчеров" aria-label="Permalink to &quot;Чем отличается от других лаунчеров?&quot;">​</a></h3><ul><li><strong>Анализ крашей.</strong> Называет мод, из-за которого упала игра, и даёт шаги с кнопками. Другие лаунчеры показывают только лог</li><li><strong>Live-мониторинг.</strong> Показывает ошибки во время игры, ещё до краша</li><li><strong>Stuzhik Connect.</strong> Сборку можно забрать у друга напрямую, без загрузки на сторонние сервисы: <a href="/guide/connect.html">Stuzhik Connect</a></li><li><strong>Сборки модов.</strong> Наборы модов без привязки к версии, применяются к любому экземпляру одной кнопкой: <a href="/guide/collections.html">Сборки модов</a></li><li><strong>Лёгкий.</strong> Быстро запускается и мало ест</li></ul><h3 id="поддерживается-ли-fabric-forge-neoforge-quilt" tabindex="-1">Поддерживается ли Fabric/Forge/NeoForge/Quilt? <a class="header-anchor" href="#поддерживается-ли-fabric-forge-neoforge-quilt" aria-label="Permalink to &quot;Поддерживается ли Fabric/Forge/NeoForge/Quilt?&quot;">​</a></h3><p><strong>Да, все четыре и Minecraft без загрузчика.</strong></p><h3 id="можно-ли-использовать-с-существующими-экземплярами" tabindex="-1">Можно ли использовать с существующими экземплярами? <a class="header-anchor" href="#можно-ли-использовать-с-существующими-экземплярами" aria-label="Permalink to &quot;Можно ли использовать с существующими экземплярами?&quot;">​</a></h3><p><strong>Да.</strong> Импорт из:</p><ul><li>MultiMC и Prism Launcher</li><li>модпаков Modrinth (<code>.mrpack</code>)</li><li>модпаков CurseForge (<code>.zip</code>)</li></ul><h3 id="требуется-ли-аккаунт-minecraft" tabindex="-1">Требуется ли аккаунт Minecraft? <a class="header-anchor" href="#требуется-ли-аккаунт-minecraft" aria-label="Permalink to &quot;Требуется ли аккаунт Minecraft?&quot;">​</a></h3><p>Да, аккаунт Microsoft с купленным Minecraft: Java Edition.</p><h3 id="что-stuzhik-отправляет-о-себе" tabindex="-1">Что Stuzhik отправляет о себе? <a class="header-anchor" href="#что-stuzhik-отправляет-о-себе" aria-label="Permalink to &quot;Что Stuzhik отправляет о себе?&quot;">​</a></h3><p><strong>Только анонимную статистику и только с вашего согласия.</strong> При первом запуске лаунчер показывает пользовательское соглашение, и пока вы не ответите, не уходит ничего.</p><ul><li><strong>Раз в сутки:</strong> версия лаунчера и её канал, операционная система и её разрядность, язык интерфейса, отметки «первый запуск за день, неделю, месяц», дата первого запуска, код приглашения, если вы пришли по нему, и ответ «Как вы узнали о Stuzhik?», если ответили</li><li><strong>Пока лаунчер открыт:</strong> короткий пульс, случайный номер сеанса (новый при каждом запуске) и какие версии Minecraft с какими загрузчиками сейчас запущены</li></ul><p><strong>Ничего личного там нет</strong>: ни ника, ни аккаунтов, ни названий сборок, ни ваших файлов, ни постоянного идентификатора установки. IP-адрес сервер не сохраняет, только определяет по нему страну. Полный список в самом соглашении. Выключить: Настройки → Приватность → «Отправлять анонимную статистику», лаунчер без неё работает так же.</p><h3 id="как-удалить-stuzhik-полностью" tabindex="-1">Как удалить Stuzhik полностью? <a class="header-anchor" href="#как-удалить-stuzhik-полностью" aria-label="Permalink to &quot;Как удалить Stuzhik полностью?&quot;">​</a></h3><p>Как обычную программу: Параметры Windows → Приложения → Stuzhik → Удалить. Служебные данные, сохранённые входы в аккаунты и правило брандмауэра уходят всегда. <strong>Сборки и миры удаляются, только если отметить</strong> «Удалить также сборки и миры (все данные лаунчера)». Подробнее: <a href="/guide/installation.html#деинсталляция">Удаление</a>.</p><h2 id="производительность" tabindex="-1">Производительность <a class="header-anchor" href="#производительность" aria-label="Permalink to &quot;Производительность&quot;">​</a></h2><h3 id="почему-forge-устанавливается-долго" tabindex="-1">Почему Forge устанавливается долго? <a class="header-anchor" href="#почему-forge-устанавливается-долго" aria-label="Permalink to &quot;Почему Forge устанавливается долго?&quot;">​</a></h3><p>Установщик Forge скачивает библиотеки с <code>maven.minecraftforge.net</code>, это 1-3 минуты. Stuzhik ускоряет это зеркалами BMCLAPI.</p><h3 id="сколько-места-занимает-экземпляр" tabindex="-1">Сколько места занимает экземпляр? <a class="header-anchor" href="#сколько-места-занимает-экземпляр" aria-label="Permalink to &quot;Сколько места занимает экземпляр?&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Что</th><th>Размер</th></tr></thead><tbody><tr><td>Minecraft</td><td>~200 МБ</td></tr><tr><td>Forge или Fabric</td><td>~50 МБ</td></tr><tr><td>Моды (10-50 штук)</td><td>~100-500 МБ</td></tr><tr><td><strong>Итого</strong></td><td><strong>~400-800 МБ</strong></td></tr></tbody></table><h3 id="можно-ли-запустить-несколько-экземпляров-одновременно" tabindex="-1">Можно ли запустить несколько экземпляров одновременно? <a class="header-anchor" href="#можно-ли-запустить-несколько-экземпляров-одновременно" aria-label="Permalink to &quot;Можно ли запустить несколько экземпляров одновременно?&quot;">​</a></h3><p>Да, без ограничений.</p><h2 id="моды" tabindex="-1">Моды <a class="header-anchor" href="#моды" aria-label="Permalink to &quot;Моды&quot;">​</a></h2><h3 id="как-установить-мод" tabindex="-1">Как установить мод? <a class="header-anchor" href="#как-установить-мод" aria-label="Permalink to &quot;Как установить мод?&quot;">​</a></h3><p>Страница сборки → «Моды» → «Каталог» → найдите мод → «Установить». <strong>Зависимости встанут вместе с модом.</strong> Свой <code>.jar</code> можно перетащить в окно. Подробнее: <a href="/guide/mods.html">Моды</a>.</p><h3 id="stuzhik-автоматически-обновляет-моды" tabindex="-1">Stuzhik автоматически обновляет моды? <a class="header-anchor" href="#stuzhik-автоматически-обновляет-моды" aria-label="Permalink to &quot;Stuzhik автоматически обновляет моды?&quot;">​</a></h3><p><strong>Только те, у которых включено автообновление</strong> (значок в строке мода): найденное обновление ставится при проверке обновлений. Получат ли его новые моды, решает «Настройки → Моды». <strong>Закреплённую версию лаунчер не обновляет никогда.</strong></p><h3 id="что-делать-при-конфликте-модов" tabindex="-1">Что делать при конфликте модов? <a class="header-anchor" href="#что-делать-при-конфликте-модов" aria-label="Permalink to &quot;Что делать при конфликте модов?&quot;">​</a></h3><ul><li><strong>Вкладка «Зависимости»</strong>: недостающие зависимости, несовместимые пары и моды «Не для этой сборки» (другая версия игры или загрузчик)</li><li><strong>«Пересечения»</strong>: моды, которые меняют один и тот же код или дают разные предметы на один крафт</li><li>Игра уже упала: <a href="/guide/log-analyzer.html">анализатор логов</a> назовёт виновника и предложит обновить или отключить его кнопкой</li></ul><h3 id="где-хранятся-моды" tabindex="-1">Где хранятся моды? <a class="header-anchor" href="#где-хранятся-моды" aria-label="Permalink to &quot;Где хранятся моды?&quot;">​</a></h3><p>В папке сборки внутри папки данных лаунчера: <code>instances/&lt;сборка&gt;/mods</code>. Где лежит папка данных и как перенести её на другой диск, рассказано ниже.</p><h3 id="можно-ли-перенести-данные-лаунчера-на-другои-диск" tabindex="-1">Можно ли перенести данные лаунчера на другой диск? <a class="header-anchor" href="#можно-ли-перенести-данные-лаунчера-на-другои-диск" aria-label="Permalink to &quot;Можно ли перенести данные лаунчера на другой диск?&quot;">​</a></h3><p><strong>Да:</strong> «Настройки → Хранилище → Расположение». Сборки, миры, Java, база и журналы переезжают вместе: на тот же диск мгновенно, на другой копированием со сверкой каждого файла, после чего старая папка удаляется. У новых установок на Windows данные сразу лежат рядом с программой. Подробнее: <a href="/guide/instances.html#data-location">Где лежат данные</a>.</p><h3 id="есть-портативныи-режим" tabindex="-1">Есть портативный режим? <a class="header-anchor" href="#есть-портативныи-режим" aria-label="Permalink to &quot;Есть портативный режим?&quot;">​</a></h3><p><strong>Да.</strong> Положите файл <code>portable.txt</code> рядом с программой: все данные, включая настройки интерфейса, будут в папке <code>data</code> рядом с ней. Так лаунчер можно носить на флешке.</p><h3 id="есть-stuzhik-для-linux" tabindex="-1">Есть Stuzhik для Linux? <a class="header-anchor" href="#есть-stuzhik-для-linux" aria-label="Permalink to &quot;Есть Stuzhik для Linux?&quot;">​</a></h3><p><strong>Да, с версии 0.0.24</strong> (пока бета): AppImage, .deb и .rpm на <a href="/download.html#linux">странице скачивания</a>. Нужны x86_64 и glibc 2.38 или новее: Debian 13, Ubuntu 24.04, Fedora 39 и новее.</p><p>Для серверов есть <a href="/guide/cli.html">консольная версия</a> <code>stuzhik-cli</code>: создаёт, ставит и запускает серверы на любом загрузчике, работает службой systemd, разбирает логи и идёт на любом Linux, в том числе на ARM.</p><h3 id="можно-показать-в-discord-во-что-я-играю" tabindex="-1">Можно показать в Discord, во что я играю? <a class="header-anchor" href="#можно-показать-в-discord-во-что-я-играю" aria-label="Permalink to &quot;Можно показать в Discord, во что я играю?&quot;">​</a></h3><p>Да, это «Настройки → Discord». Пока идёт игра, в профиле видно «Играет в Stuzhik» с версией Minecraft, загрузчиком и временем в игре. Что именно показывать, выбираете вы, и там же видно, как статус увидят другие.</p><p><strong>На публичном сервере друзья могут попроситься к вам через Discord</strong>: их лаунчер поставит нужную сборку и сразу подключит к серверу.</p><h2 id="stuzhik-connect" tabindex="-1">Stuzhik Connect <a class="header-anchor" href="#stuzhik-connect" aria-label="Permalink to &quot;Stuzhik Connect&quot;">​</a></h2><h3 id="это-безопасно" tabindex="-1">Это безопасно? <a class="header-anchor" href="#это-безопасно" aria-label="Permalink to &quot;Это безопасно?&quot;">​</a></h3><p><strong>Да.</strong> Соединение шифруется целиком (QUIC с TLS 1.3), друга лаунчер узнаёт по подписи его ключом, а <strong>сборку у вас забирают только после вашего «Разрешить»</strong> (так по умолчанию; в настройках выдачи «Спрашивать разрешение» можно переключить на «Кроме друзей» или «Никогда»). Исполняемые файлы не передаются никогда. Подробнее: <a href="/guide/connect.html#безопасность">Stuzhik Connect</a>.</p><h3 id="нужно-открывать-порты-на-роутере" tabindex="-1">Нужно открывать порты на роутере? <a class="header-anchor" href="#нужно-открывать-порты-на-роутере" aria-label="Permalink to &quot;Нужно открывать порты на роутере?&quot;">​</a></h3><p><strong>Нет.</strong> В локальной сети устройства находят друг друга сами. Для друзей вне вашей сети (разные квартиры, города) проще всего общий VPN, и тогда пробрасывать порты тоже не нужно: в Radmin VPN, ZeroTier и Hamachi поиск работает как в локалке, а в Tailscale друга один раз добавляют по адресу, дальше лаунчер находит его сам.</p><p>На Windows нужно одно правило брандмауэра, «Stuzhik Connect»: его добавляет кнопка в разделе «Друзья».</p><h3 id="работает-через-интернет-напрямую-без-vpn" tabindex="-1">Работает через интернет напрямую, без VPN? <a class="header-anchor" href="#работает-через-интернет-напрямую-без-vpn" aria-label="Permalink to &quot;Работает через интернет напрямую, без VPN?&quot;">​</a></h3><p><strong>Нет, если вы в разных сетях.</strong> У Stuzhik нет своего сервера для соединения через интернет: он находит и связывает устройства только в пределах одной сети, настоящей или виртуальной через VPN. В одной локалке работает само, в разных сетях нужен общий VPN: <a href="/guide/connect.html#если-вы-в-разных-сетях">Stuzhik Connect</a>.</p><h2 id="проблемы" tabindex="-1">Проблемы <a class="header-anchor" href="#проблемы" aria-label="Permalink to &quot;Проблемы&quot;">​</a></h2><h3 id="outofmemoryerror" tabindex="-1">OutOfMemoryError <a class="header-anchor" href="#outofmemoryerror" aria-label="Permalink to &quot;OutOfMemoryError&quot;">​</a></h3><p><strong>Игре не хватило выделенной памяти.</strong> <a href="/guide/log-analyzer.html">Анализатор логов</a> узнает это сам и предложит «Увеличить выделенную память». Вручную: меню сборки → «Редактировать» → память (для модпаков обычно 4-6 ГБ).</p><h3 id="игра-не-запускается" tabindex="-1">Игра не запускается <a class="header-anchor" href="#игра-не-запускается" aria-label="Permalink to &quot;Игра не запускается&quot;">​</a></h3><p>Откройте вкладку «Анализ логов» сборки: <a href="/guide/log-analyzer.html">анализатор</a> покажет главную причину и что сделать. Перед запуском лаунчер сам проверяет сборку и предупреждает о модах не для этой версии игры или загрузчика. Нужную Java он ставит сам.</p><h3 id="моды-не-загружаются" tabindex="-1">Моды не загружаются <a class="header-anchor" href="#моды-не-загружаются" aria-label="Permalink to &quot;Моды не загружаются&quot;">​</a></h3><p><strong>Мод должен быть для загрузчика и версии игры сборки</strong>: другие вкладка «Зависимости» показывает группой «Не для этой сборки», с кнопкой «Отключить». Если мод требует другой (например, Fabric API), там же «Установить все недостающие».</p><h3 id="краш-с-mixin" tabindex="-1">Краш с &quot;Mixin&quot; <a class="header-anchor" href="#краш-с-mixin" aria-label="Permalink to &quot;Краш с &quot;Mixin&quot;&quot;">​</a></h3><p><strong>Моды меняют один и тот же код игры, и одно изменение не применилось.</strong> Анализатор логов читает раздел <code>Mixins in Stacktrace</code> отчёта и называет моды, чьи mixin&#39;ы меняли упавший код. Где моды наступают друг другу на ноги, заранее показывает вкладка <a href="/guide/mods.html#overlaps">«Пересечения»</a>.</p><h2 id="обратная-связь" tabindex="-1">Обратная связь <a class="header-anchor" href="#обратная-связь" aria-label="Permalink to &quot;Обратная связь&quot;">​</a></h2><h3 id="как-сообщить-о-баге-или-предложить-фичу" tabindex="-1">Как сообщить о баге или предложить фичу? <a class="header-anchor" href="#как-сообщить-о-баге-или-предложить-фичу" aria-label="Permalink to &quot;Как сообщить о баге или предложить фичу?&quot;">​</a></h3><p>Напишите в <a href="https://t.me/stuzhik_launcher" target="_blank" rel="noreferrer">Telegram</a>: там же анонсы обновлений.</p>',64)])])}const f=t(i,[["render",n]]);export{g as __pageData,f as default};
